def transform(grid):
 h=len(grid); w=len(grid[0]); candidates=[[],[]]
 for r in range(h-2):
  for c in range(w-1):
   color=grid[r][c]
   if not color: continue
   for d in range(c+1,w):
    if grid[r][d]!=color: break
    for b in range(r+2,h):
     if any(grid[b][x]!=color for x in range(c,d+1)): continue
     for side in range(2):
      edge=d if side==0 else c
      if any(grid[y][edge]!=color for y in range(r,b+1)): continue
      cols=range(c,d) if side==0 else range(c+1,d+1)
      vals=[[grid[y][x] for x in cols] for y in range(r+1,b)]
      if any(v==0 for row in vals for v in row): continue
      if not any(v!=color for row in vals for v in row): continue
      candidates[side].append((r,c,b,d,vals))
 best=None
 for a in candidates[0]:
  for b in candidates[1]:
   if a[3]>=b[1] or len(a[4])!=len(b[4]): continue
   score=(len(a[4])*(len(a[4][0])+len(b[4][0])), -abs(len(a[4][0])-len(b[4][0])))
   if best is None or score>best[0]: best=(score,a,b)
 if best:
  return [x+y for x,y in zip(best[2][4],best[1][4])]
 return grid

